-- 世界杯项目结构草案：20张业务表，尚未导入。
-- 仅在独立空数据库wc_portal中执行，不包含校园数据库的数据或配置。
SET NAMES utf8mb4;

CREATE TABLE `wc_sys_user` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', username VARCHAR(64) NOT NULL UNIQUE COMMENT '登录名', email VARCHAR(255) NOT NULL UNIQUE COMMENT '邮箱', auth_key VARCHAR(32) NOT NULL COMMENT '身份密钥', password_hash VARCHAR(255) NOT NULL COMMENT '密码哈希', password_reset_token VARCHAR(255) NULL UNIQUE COMMENT '重置令牌', verification_token VARCHAR(255) NULL COMMENT '验证令牌', role VARCHAR(20) NOT NULL DEFAULT 'member' COMMENT '角色', status SMALLINT NOT NULL DEFAULT 10 COMMENT '账户状态', created_at INT NOT NULL COMMENT '创建时间戳', updated_at INT NOT NULL COMMENT '更新时间戳', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户账户';

CREATE TABLE `wc_sys_team` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', name VARCHAR(100) NOT NULL COMMENT '团队名称', description TEXT COMMENT '团队介绍', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='开发团队';

CREATE TABLE `wc_sys_member` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', user_id BIGINT NOT NULL UNIQUE COMMENT '账户编号', team_id BIGINT NOT NULL COMMENT '开发团队编号', display_name VARCHAR(100) NOT NULL COMMENT '姓名', student_number VARCHAR(32) COMMENT '学号', bio TEXT COMMENT '个人介绍', FOREIGN KEY(user_id) REFERENCES wc_sys_user(id), FOREIGN KEY(team_id) REFERENCES wc_sys_team(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='开发成员';

CREATE TABLE `wc_content_announcement` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', author_id BIGINT NOT NULL COMMENT '发布人', title VARCHAR(200) NOT NULL COMMENT '标题', content TEXT NOT NULL COMMENT '正文', status VARCHAR(20) NOT NULL DEFAULT 'draft' COMMENT '发布状态', published_at DATETIME COMMENT '发布时间', FOREIGN KEY(author_id) REFERENCES wc_sys_user(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公告';

CREATE TABLE `wc_sys_assignment` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', owner_id BIGINT NOT NULL COMMENT '所属用户', scope VARCHAR(20) NOT NULL COMMENT 'team或personal', title VARCHAR(255) NOT NULL COMMENT '文件名称', relative_path VARCHAR(512) NOT NULL COMMENT '相对路径', sha256 CHAR(64) NOT NULL COMMENT '摘要', FOREIGN KEY(owner_id) REFERENCES wc_sys_user(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='作业文件';

CREATE TABLE `wc_sys_audit` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', actor_id BIGINT NOT NULL COMMENT '操作人', action VARCHAR(80) NOT NULL COMMENT '动作', object_type VARCHAR(80) NOT NULL COMMENT '对象类型', object_id BIGINT COMMENT '对象编号', details TEXT COMMENT '操作摘要', FOREIGN KEY(actor_id) REFERENCES wc_sys_user(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='操作日志';

CREATE TABLE `wc_sys_notification` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', user_id BIGINT NOT NULL COMMENT '接收人', subject VARCHAR(255) NOT NULL COMMENT '主题', content TEXT NOT NULL COMMENT '通知内容', channel VARCHAR(20) NOT NULL DEFAULT 'file' COMMENT '投递渠道', status VARCHAR(20) NOT NULL DEFAULT 'pending' COMMENT '投递状态', FOREIGN KEY(user_id) REFERENCES wc_sys_user(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通知记录';

CREATE TABLE `wc_data_tournament` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', year SMALLINT NOT NULL UNIQUE COMMENT '年份', name VARCHAR(160) NOT NULL COMMENT '赛事名称', starts_at DATE NOT NULL COMMENT '开始日期', ends_at DATE NOT NULL COMMENT '结束日期', source_url VARCHAR(1000) COMMENT '来源', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='世界杯届次';

CREATE TABLE `wc_data_stage` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', tournament_id BIGINT NOT NULL COMMENT '届次编号', name VARCHAR(80) NOT NULL COMMENT '阶段名称', sort_order INT NOT NULL COMMENT '展示顺序', UNIQUE(tournament_id,name), FOREIGN KEY(tournament_id) REFERENCES wc_data_tournament(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='赛事阶段';

CREATE TABLE `wc_data_group` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', tournament_id BIGINT NOT NULL COMMENT '届次编号', name VARCHAR(20) NOT NULL COMMENT '小组名称', UNIQUE(tournament_id,name), FOREIGN KEY(tournament_id) REFERENCES wc_data_tournament(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='赛事小组';

CREATE TABLE `wc_data_stadium` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', name VARCHAR(160) NOT NULL COMMENT '球场名称', city VARCHAR(100) NOT NULL COMMENT '城市', capacity INT UNSIGNED COMMENT '容量', source_url VARCHAR(1000) COMMENT '来源', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='球场';

CREATE TABLE `wc_data_team` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', name VARCHAR(120) NOT NULL COMMENT '队名', fifa_code CHAR(3) NOT NULL UNIQUE COMMENT 'FIFA代码', confederation VARCHAR(30) COMMENT '洲足联', description TEXT COMMENT '介绍', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='国家队';

CREATE TABLE `wc_data_player` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', name VARCHAR(160) NOT NULL COMMENT '球员姓名', nationality_team_id BIGINT NOT NULL COMMENT '国家队编号', birth_date DATE COMMENT '出生日期', position VARCHAR(40) COMMENT '位置', source_url VARCHAR(1000) COMMENT '来源', FOREIGN KEY(nationality_team_id) REFERENCES wc_data_team(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='球员';

CREATE TABLE `wc_data_squad` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', tournament_id BIGINT NOT NULL COMMENT '届次', team_id BIGINT NOT NULL COMMENT '国家队', player_id BIGINT NOT NULL COMMENT '球员', group_id BIGINT COMMENT '所属小组', shirt_number SMALLINT COMMENT '球衣号码', UNIQUE(tournament_id,team_id,player_id), FOREIGN KEY(tournament_id) REFERENCES wc_data_tournament(id), FOREIGN KEY(team_id) REFERENCES wc_data_team(id), FOREIGN KEY(player_id) REFERENCES wc_data_player(id), FOREIGN KEY(group_id) REFERENCES wc_data_group(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='参赛阵容';

CREATE TABLE `wc_data_match` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', tournament_id BIGINT NOT NULL COMMENT '届次', stage_id BIGINT NOT NULL COMMENT '阶段', group_id BIGINT COMMENT '小组', stadium_id BIGINT NOT NULL COMMENT '球场', match_number INT NOT NULL COMMENT '届内比赛编号', home_team_id BIGINT NOT NULL COMMENT '主队', away_team_id BIGINT NOT NULL COMMENT '客队', kicks_off_at DATETIME NOT NULL COMMENT 'UTC开赛时间', normal_home SMALLINT UNSIGNED COMMENT '常规主队进球', normal_away SMALLINT UNSIGNED COMMENT '常规客队进球', extra_home SMALLINT UNSIGNED COMMENT '加时主队进球', extra_away SMALLINT UNSIGNED COMMENT '加时客队进球', penalty_home SMALLINT UNSIGNED COMMENT '点球大战主队命中', penalty_away SMALLINT UNSIGNED COMMENT '点球大战客队命中', status VARCHAR(20) NOT NULL DEFAULT 'scheduled' COMMENT '比赛状态', source_key VARCHAR(160) UNIQUE COMMENT '来源去重键', UNIQUE(tournament_id,match_number), FOREIGN KEY(tournament_id) REFERENCES wc_data_tournament(id), FOREIGN KEY(stage_id) REFERENCES wc_data_stage(id), FOREIGN KEY(group_id) REFERENCES wc_data_group(id), FOREIGN KEY(stadium_id) REFERENCES wc_data_stadium(id), FOREIGN KEY(home_team_id) REFERENCES wc_data_team(id), FOREIGN KEY(away_team_id) REFERENCES wc_data_team(id), CHECK(home_team_id<>away_team_id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='比赛';

CREATE TABLE `wc_data_event` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', match_id BIGINT NOT NULL COMMENT '比赛编号', player_id BIGINT COMMENT '球员', team_id BIGINT NOT NULL COMMENT '所属队', minute SMALLINT UNSIGNED NOT NULL COMMENT '分钟', added_minute SMALLINT UNSIGNED NOT NULL DEFAULT 0 COMMENT '补时分钟', type VARCHAR(30) NOT NULL COMMENT '事件类型', source_key VARCHAR(160) UNIQUE COMMENT '来源去重键', FOREIGN KEY(match_id) REFERENCES wc_data_match(id), FOREIGN KEY(player_id) REFERENCES wc_data_player(id), FOREIGN KEY(team_id) REFERENCES wc_data_team(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='比赛事件';

CREATE TABLE `wc_fan_post` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', user_id BIGINT NOT NULL COMMENT '作者', match_id BIGINT COMMENT '关联比赛', title VARCHAR(200) NOT NULL COMMENT '话题标题', content TEXT NOT NULL COMMENT '话题内容', status VARCHAR(20) NOT NULL DEFAULT 'pending' COMMENT '审核状态', FOREIGN KEY(user_id) REFERENCES wc_sys_user(id), FOREIGN KEY(match_id) REFERENCES wc_data_match(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='球迷话题';

CREATE TABLE `wc_fan_comment` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', post_id BIGINT NOT NULL COMMENT '话题编号', user_id BIGINT NOT NULL COMMENT '作者', parent_id BIGINT COMMENT '回复对象', content TEXT NOT NULL COMMENT '评论内容', status VARCHAR(20) NOT NULL DEFAULT 'pending' COMMENT '审核状态', FOREIGN KEY(post_id) REFERENCES wc_fan_post(id), FOREIGN KEY(user_id) REFERENCES wc_sys_user(id), FOREIGN KEY(parent_id) REFERENCES wc_fan_comment(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='话题评论及回复';

CREATE TABLE `wc_fan_team_favorite` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', user_id BIGINT NOT NULL COMMENT '用户', team_id BIGINT NOT NULL COMMENT '球队', UNIQUE(user_id,team_id), FOREIGN KEY(user_id) REFERENCES wc_sys_user(id), FOREIGN KEY(team_id) REFERENCES wc_data_team(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='球队收藏';

CREATE TABLE `wc_fan_match_favorite` (id BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键', user_id BIGINT NOT NULL COMMENT '用户', match_id BIGINT NOT NULL COMMENT '比赛', UNIQUE(user_id,match_id), FOREIGN KEY(user_id) REFERENCES wc_sys_user(id), FOREIGN KEY(match_id) REFERENCES wc_data_match(id), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间', updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间', PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='比赛收藏';
